// Lit l'onglet profil, même si les en-têtes ont un espace ou un accent
const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const p = {};
let chat_id = '';
for (const i of $input.all()) {
  const j = i.json;
  const kCle = Object.keys(j).find(k => norm(k) === 'cle');
  const kVal = Object.keys(j).find(k => norm(k) === 'valeur');
  const cle = String(j[kCle] ?? '').trim();
  const val = String(j[kVal] ?? '').trim();
  if (!cle) continue;
  if (cle === 'chat_id') { chat_id = val; continue; }
  if (cle.startsWith('_') || !val) continue;   // lignes techniques (_modif_en_attente) ou vides
  p[cle] = val;
}
return [{ json: { profil: p, profil_texte: JSON.stringify(p), chat_id } }];

// MODE DÉMO : ces offres ne sont ajoutées que si tu lances le workflow à la main
// (bouton Execute workflow). La recherche automatique de 3 h ne les ajoute jamais.
if ($execution.mode !== 'test') return [];

const run = Date.now().toString(36);            // identifiant unique à chaque lancement
const dans = j => new Date(Date.now() + j * 86400000).toISOString().slice(0, 10);
const lien = t => 'https://www.google.com/search?q=' + encodeURIComponent(t);

return [
  { json: { offer_id: 'D' + run + '1', intitule: 'Stage Data Scientist – IA générative', societe: 'NovaMobility', ville: 'Paris', pays: 'France', contrat: 'Stage', duree: '6 mois', salaire: '1 500 € / mois', deadline: dans(10), lien: lien('stage data scientist IA générative Paris'), texte: 'Stage de 6 mois à Paris dans l’équipe R&D véhicule autonome. Modèles de diffusion pour la planification de trajectoire, Python, PyTorch, évaluation de modèles. Anglais courant. Profil école d’ingénieurs ou double diplôme data et management.' } },
  { json: { offer_id: 'D' + run + '2', intitule: 'Stage Machine Learning Engineer – Computer Vision', societe: 'Lumen Health', ville: 'Paris', pays: 'France', contrat: 'Stage', duree: '5 à 6 mois', salaire: '1 400 € / mois', deadline: dans(20), lien: lien('stage machine learning computer vision Paris'), texte: 'Startup en imagerie médicale. Entraînement et déploiement de modèles de vision par ordinateur, deep learning, Python. Bureau à Paris, deux jours de télétravail par semaine.' } },
  { json: { offer_id: 'D' + run + '3', intitule: 'Stage Consultant·e Data & IA', societe: 'Atlas Conseil', ville: 'Paris', pays: 'France', contrat: 'Stage', duree: '6 mois', salaire: '1 600 € / mois', deadline: dans(30), lien: lien('stage consultant data IA Paris'), texte: 'Cabinet de conseil en stratégie data. Missions de cadrage de projets IA pour de grands groupes, analyse de données, SQL, Python, restitution aux clients.' } },
  { json: { offer_id: 'D' + run + '4', intitule: 'Vendeur·se en boutique', societe: 'Maison Lenoir', ville: 'Lyon', pays: 'France', contrat: 'CDI', duree: 'Temps plein', salaire: 'SMIC', deadline: '', lien: lien('vendeur boutique Lyon CDI'), texte: 'Accueil et conseil client en boutique de prêt-à-porter, gestion des stocks, encaissement. Disponible le samedi.' } }
];

return $input.all().map(item => {
  const o = item.json;
  return {
    json: {
      id: String(o.offer_id || '').trim(),
      titre: (o.intitule || '').trim(),
      entreprise: (o.societe || '').trim(),
      lieu: (o.ville || '').trim(),
      pays: (o.pays || '').trim(),
      remote: 'non précisé',
      type_contrat: o.contrat || 'non précisé',
      duree: o.duree || 'non précisée',
      salaire: o.salaire || 'non précisé',
      deadline: o.deadline || '',
      url: (o.lien || '').trim(),
      source: 'démo',
      description: (o.texte || '').trim().slice(0, 1500)
    }
  };
});

// 1) enlève les offres déjà dans le Sheet  2) enlève les doublons entre sources
// 3) garde les offres liées à tes domaines  4) enlève les mots exclus  5) max 15 offres (quota IA)
const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const get = (j, key) => { const k = Object.keys(j).find(x => norm(x) === key); return k ? j[k] : ''; };

const connues = $('Lire offres connues').all().map(i => i.json);
const dejaIds = new Set(connues.map(j => String(get(j, 'id'))).filter(Boolean));
const dejaTitres = new Set(connues.map(j => norm(get(j, 'titre')) + '|' + norm(get(j, 'entreprise'))).filter(t => t !== '|'));

const profil = $('Profil en objet').first().json.profil || {};
const pget = key => { const k = Object.keys(profil).find(x => norm(x).startsWith(key)); return k ? profil[k] : ''; };
const motsDomaines = {
  'data/ia': ['data', 'machine learning', 'deep learning', ' ml ', ' ai ', ' ia ', 'intelligence artificielle', 'scientist', 'analytics', 'llm', 'computer vision', 'nlp'],
  'software / tech': ['software', 'developer', 'developpeur', 'engineer', 'backend', 'frontend', 'full stack', 'devops', 'cloud'],
  'ingenierie / r&d': ['r&d', 'research', 'recherche', 'ingenieur', 'engineer', 'aerospace', 'robotics', 'robotique'],
  'conseil': ['consult', 'conseil', 'strategy', 'strategie'],
  'finance': ['finance', 'financial', 'banking', 'audit', 'investment', 'm&a', 'private equity'],
  'produit': ['product', 'produit'],
  'marketing': ['marketing', 'growth', 'brand', 'communication'],
  'supply chain / operations': ['supply chain', 'logistics', 'logistique', 'operations', 'procurement', 'achats'],
  'entrepreneuriat': ['founder', 'entrepreneur', 'business developer', 'startup']
};
const mots = [];
for (const d of String(pget('domaines')).split(',')) mots.push(...(motsDomaines[norm(d)] || []));
for (const w of String(pget('autre domaine')).split(/[,;]/)) if (norm(w)) mots.push(norm(w));
const exclus = String(pget('mots a exclure') || pget('mot a exclure')).split(/[,;]/).map(norm).filter(Boolean);

const MAX = 15;
const vus = new Set();
const resultat = [];
for (const i of $('Offre valide ?').all()) {
  const o = i.json;
  const demo = o.source === 'démo';
  const cle = norm(o.titre) + '|' + norm(o.entreprise);
  if (dejaIds.has(String(o.id)) || vus.has(cle)) continue;
  if (!demo && dejaTitres.has(cle)) continue;          // les offres de démo peuvent revenir à chaque répétition
  const texte = ' ' + norm(o.titre + ' ' + o.description).replace(/[^a-z0-9/&]+/g, ' ') + ' ';
  if (exclus.some(m => texte.includes(m))) continue;
  if (!demo && mots.length && !mots.some(m => texte.includes(m))) continue;   // la démo garde aussi l'offre hors sujet, pour montrer la note basse
  vus.add(cle);
  resultat.push(i);
  if (resultat.length >= MAX) break;
}
return resultat;

