// Associe chaque note de l'IA à son offre grâce à l'id (validation du schéma + repli si illisible)
const offres = $('Retirer doublons').all().map(i => i.json);
const brut = String($input.first().json.text || $input.first().json.output || '');
let notes = [];
try {
  const propre = brut.replace(/```json|```/g, '').trim();
  notes = JSON.parse(propre.slice(propre.indexOf('['), propre.lastIndexOf(']') + 1));
} catch (e) {}
const parId = {};
for (const n of (Array.isArray(notes) ? notes : [])) if (n && n.id !== undefined) parId[String(n.id)] = n;
const maintenant = new Date().toISOString();

return offres.map(o => {
  const n = parId[String(o.id)];
  const brutScore = n ? Number(n.score) : NaN;
  const score = Number.isFinite(brutScore) && brutScore >= 0 && brutScore <= 10 ? Math.round(brutScore) : -1;
  return { json: {
    ...o,
    score,
    resume: (n && (n.resume || n.summary)) || '',
    raison: (n && (n.raison || n.reason || n.justification)) || (n ? '' : 'réponse IA illisible'),
    statut: score < 0 ? 'erreur IA' : 'nouveau',
    date_ajout: maintenant,
    date_decision: ''
  }};
});

const strip = h => String(h || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const types = { full_time: 'Temps plein', part_time: 'Temps partiel', contract: 'Contrat / CDD', internship: 'Stage', freelance: 'Freelance', other: 'Autre' };
const jobs = $input.all().flatMap(i => Array.isArray(i.json.jobs) ? i.json.jobs : []);
return jobs.map(j => ({ json: {
  id: j.id ? 'R' + j.id : '',
  titre: String(j.title || '').trim(),
  entreprise: String(j.company_name || '').trim(),
  lieu: String(j.candidate_required_location || 'Remote').trim(),
  pays: String(j.candidate_required_location || '').trim(),
  remote: 'oui',
  type_contrat: types[j.job_type] || j.job_type || 'non précisé',
  duree: 'non précisée',
  salaire: String(j.salary || '').trim() || 'non précisé',
  deadline: '',
  url: String(j.url || '').trim(),
  source: 'Remotive',
  description: strip(j.description).slice(0, 1500)
}}));

const strip = h => String(h || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
// identifiant court (Telegram limite les boutons à 64 octets)
const hash = s => { let h = 5381; for (const c of String(s)) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(36); };
const jobs = $input.all().flatMap(i => Array.isArray(i.json.data) ? i.json.data : []);
return jobs.map(j => {
  const t = (j.job_types || []).join(', ');
  const stage = /intern|praktik|stage|trainee|werkstudent|apprenti/i.test((j.title || '') + ' ' + t);
  return { json: {
    id: 'A' + hash(j.slug || j.url || j.title),
    titre: String(j.title || '').trim(),
    entreprise: String(j.company_name || '').trim(),
    lieu: String(j.location || '').trim(),
    pays: '',
    remote: j.remote ? 'oui' : 'non précisé',
    type_contrat: stage ? 'Stage' : (t || 'non précisé'),
    duree: 'non précisée',
    salaire: 'non précisé',
    deadline: '',
    url: String(j.url || '').trim(),
    source: 'Arbeitnow',
    description: strip(j.description).slice(0, 1500)
  }};
});

const offres = $input.all().map(i => i.json);
const lot = offres.map(o => ({
  id: o.id, titre: o.titre, entreprise: o.entreprise, lieu: o.lieu, pays: o.pays,
  remote: o.remote, type_contrat: o.type_contrat, duree: o.duree, salaire: o.salaire,
  description: String(o.description || '').slice(0, 600)
}));
return [{ json: { nb: lot.length, offres_json: JSON.stringify(lot) } }];
